// Un item por correo con PDF; arma la petición a Claude. Sin PDF adjunto → se ignora.
const SISTEMA = "Clasificas los correos que llegan al buzón de facturas de proveedores de CEFER (Instituto de Reproducción CEFER S.L., CIF B60508918).\nRecibes el remitente, el asunto, el cuerpo y los PDF adjuntos. Responde SOLO con un objeto JSON, sin texto adicional:\n{\"categoria\": \"...\", \"motivo\": \"frase corta\", \"pdfs_factura\": [\"nombre exacto de cada PDF adjunto que sea una factura\"]}\n\nCategorías:\n- \"factura_nueva\": un proveedor envía a CEFER una o varias facturas (o recibos con valor de factura) para registrarlas o pagarlas. Incluye facturas de suscripciones, domiciliaciones y pagos con tarjeta.\n- \"reclamacion_o_consulta\": recordatorio o reclamación de pago, consulta, queja o conversación sobre una factura ya enviada, aunque adjunte una copia.\n- \"otro\": publicidad, presupuestos, proformas, pedidos, albaranes, justificantes de transferencia, extractos, contratos, notificaciones sin factura, facturas emitidas POR CEFER.\n- \"dudoso\": no está claro, o es una factura rectificativa / abono, o mezcla una factura nueva con una reclamación.\n\nEn \"pdfs_factura\" pon solo los adjuntos que son facturas (vacío si no hay ninguno).";
const MAX_BYTES = 15 * 1024 * 1024; // PDFs que se envían a Claude (el resto solo por nombre)
// Correos internos que reenvían facturas ya registradas (solo confirman que son correctas): se ignoran.
const EXCLUIDOS = ['bancosemen@icefer.es', 'laboratorio@icefer.es', 'dues@icefer.es'];
// Las ejecuciones manuales de prueba cogen un correo cualquiera (a veces de hace años): se ignoran los antiguos.
const MAX_DIAS = 7;
const salida = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const m = item.json;
  const pdfs = [];
  for (const [clave, b] of Object.entries(item.binary || {})) {
    const nombre = b.fileName || clave;
    if ((b.mimeType || '').includes('pdf') || nombre.toLowerCase().endsWith('.pdf')) pdfs.push({ clave, nombre });
  }
  if (pdfs.length === 0) continue;

  const remitente = m.from?.emailAddress?.address || m.sender?.emailAddress?.address || '';
  if (EXCLUIDOS.includes(remitente.toLowerCase())) continue;
  if (m.receivedDateTime && Date.now() - new Date(m.receivedDateTime).getTime() > MAX_DIAS * 86400000) continue;
  const asunto = m.subject || '';
  const cuerpo = (m.body?.content || m.bodyPreview || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim().slice(0, 4000);

  const contenido = [];
  let bytes = 0;
  for (const p of pdfs) {
    const buf = await this.helpers.getBinaryDataBuffer(i, p.clave);
    if (bytes + buf.length > MAX_BYTES) continue;
    bytes += buf.length;
    contenido.push({ type: 'document', title: p.nombre,
      source: { type: 'base64', media_type: 'application/pdf', data: buf.toString('base64') } });
  }
  contenido.push({ type: 'text', text:
    `Remitente: ${remitente}\nAsunto: ${asunto}\nPDF adjuntos: ${pdfs.map(p => p.nombre).join(', ')}\n\nCuerpo del correo:\n${cuerpo}` });

  salida.push({
    json: {
      messageId: m.id, remitente, asunto, pdfs,
      peticion: { model: 'claude-haiku-5-5', max_tokens: 500, system: SISTEMA,
                  messages: [{ role: 'user', content: contenido }] },
    },
    binary: item.binary,
    pairedItem: { item: i },
  });
}
return salida;

// Lee la respuesta de Claude. Si falla o no se entiende → "dudoso" (el correo va a Facturas/Revisar).
const prep = $('Preparar clasificación').all();
const validas = ['factura_nueva', 'reclamacion_o_consulta', 'otro', 'dudoso'];
return $input.all().map((it, i) => {
  const p = prep[i];
  let r;
  try {
    const texto = (it.json.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
    r = JSON.parse(texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1));
  } catch (e) {
    r = { categoria: 'dudoso', motivo: 'Respuesta de la IA no interpretable: ' + JSON.stringify(it.json).slice(0, 300) };
  }
  if (!validas.includes(r.categoria)) r.categoria = 'dudoso';
  const { peticion, ...datos } = p.json;
  return {
    json: { ...datos, categoria: r.categoria, motivo: r.motivo || '',
            pdfsFactura: Array.isArray(r.pdfs_factura) ? r.pdfs_factura : [] },
    binary: p.binary,
    pairedItem: { item: i },
  };
});

// Un item por PDF de factura, con el binario en "data" y los datos del correo.
// Las "properties" de Drive admiten 124 bytes por clave+valor: se recortan.
const recortar = (s, max) => { let r = s || ''; while (Buffer.byteLength(r, 'utf8') > max) r = r.slice(0, -1); return r; };
const out = [];
const items = $input.all();
items.forEach((it, i) => {
  const j = it.json;
  const elegidos = j.pdfs.filter(p => j.pdfsFactura.includes(p.nombre));
  for (const p of (elegidos.length ? elegidos : j.pdfs)) {
    out.push({
      json: { messageId: j.messageId, nombre: p.nombre,
              remitente: recortar(j.remitente, 110), asunto: recortar(j.asunto, 110),
              descripcion: `Correo de ${j.remitente}\nAsunto: ${j.asunto}\nClasificación: ${j.motivo}` },
      binary: { data: it.binary[p.clave] },
      pairedItem: { item: i },
    });
  }
});
return out;

// Tras subir todos los PDF, un item por correo para moverlo a Facturas/Procesadas.
const vistos = new Set();
return $('Un item por PDF').all()
  .filter(it => !vistos.has(it.json.messageId) && vistos.add(it.json.messageId))
  .map(it => ({ json: { messageId: it.json.messageId } }));
